{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 7,
      "text_ar": "ولكن الفضة أكثر وفرة من الذهب، والنحاس من الفضة، والحديد من النحاس، والرصاص من الحديد، والطين من الرصاص.",
      "verse": 56
    },
    {
      "chapter": 7,
      "text_ar": "فاحكم إذن أي الأشياء هي الثمينة والمرغوبة، وما هو وفير وما هو نادر؟",
      "verse": 57
    },
    {
      "chapter": 7,
      "text_ar": "فقلت: «يا رب السيد، إن ما هو وفير هو أقل قيمة، لأن ما هو أكثر ندرة هو أكثر ثمنًا».",
      "verse": 58
    },
    {
      "chapter": 7,
      "text_ar": "فأجابني: «زن في نفسك الأشياء التي فكرت فيها، لأن من يمتلك ما يصعب الحصول عليه يفرح بالذي يمتلك ما هو وفير.",
      "verse": 59
    },
    {
      "chapter": 7,
      "text_ar": "وهكذا هو الدينونة التي وعدت بها؛ فإني سأفرح بالقليلين الذين سيخلصون، لأن هؤلاء هم الذين جعلوا مجدي يسود الآن، وبهم يُكرم اسمي الآن».",
      "verse": 60
    }
  ]
}
